//! Worldgen P23 evaluation and observability contract.
//! Binds benchmark observations to baselines, uncertainty, provenance, and release gates.
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::json;
use std::collections::BTreeSet;
use thiserror::Error;

pub const FEATURE_ID:&str="AFA-worldgen-P23-F01";pub const CONTRACT_VERSION:&str="worldgen-local-evaluation-observability/1.0";pub const CONTENT_TYPE:&str="application/vnd.aurora.worldgen.evaluation-observability-receipt-1+json";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct EvaluationObservation4{pub observation_id:String,pub metric:String,pub value_milli:i64,pub baseline_milli:i64,pub uncertainty_milli:u64,pub evidence_state:String,pub provenance_digest:ContentHash,pub replay_identity:ContentHash,pub independent_site:String,pub negative_result:bool,pub local:bool,pub aggregate_only:bool}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct EvaluationRequest4{pub request_id:String,pub scope:String,pub benchmark_id:String,pub observations:Vec<EvaluationObservation4>,pub required_metric_order:Vec<String>,pub min_pass_fraction_milli:u32,pub policy_allowed:bool,pub protected_closure:bool,pub signed_approval:bool,pub network_available:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub replay_identity:ContentHash,pub adversarial_events:Vec<String>,pub action_budget:u32,pub action_count:u32,pub stage_order:Vec<String>,pub completed_stage_order:Vec<String>,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct EvaluationArtifact4{pub artifact_id:String,pub content_type:String,pub content_hash:ContentHash,pub semantic_loss:Vec<String>,pub provenance_digests:Vec<ContentHash>,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct EvaluationCard8{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub mode:String,pub scale:String,pub request_id:String,pub benchmark_id:String,pub disposition:String,pub observation_order:Vec<String>,pub passed_order:Vec<String>,pub failed_order:Vec<String>,pub unknown_order:Vec<String>,pub unmeasured_order:Vec<String>,pub contradicted_order:Vec<String>,pub omitted_order:Vec<String>,pub baseline_delta_order:Vec<String>,pub uncertainty_order:Vec<String>,pub negative_evidence_order:Vec<String>,pub site_order:Vec<String>,pub metric_order:Vec<String>,pub replay_identity:ContentHash,pub evaluation_digest:ContentHash,pub artifact:EvaluationArtifact4,pub effect_receipts:Vec<String>,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum EvaluationObservabilityError{#[error("invalid evaluation request: {0}")]Invalid(String),#[error("evaluation card failed validation: {0}")]Output(String)}
fn ord(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}fn dig(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn ne(v:&str)->bool{!v.trim().is_empty()}
pub fn manifest(id:&str,version:&str,scale:&str,mode:&str)->serde_json::Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":id,"version":version,"owner_crate":"worldgen","consumers":["evaluation scientist","benchmark steward","research program lead","release operator"],"behavior":format!("evaluate benchmark observations with baseline and uncertainty witnesses at {scale} ({mode})"),"value":"makes release claims falsifiable, replayable, and honest about null, unknown, and negative outcomes","input_schema":"EvaluationRequest4@1","output_schema":"EvaluationCard8@1","effects":["emit:evaluation-card","block:unsafe-release"],"permissions":["read:local-evaluation-observations"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":PRECLINICAL_BOUNDARY})}
impl EvaluationCard8{pub fn validate(&self)->Result<(),EvaluationObservabilityError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||!ne(&self.contract_version)||!ne(&self.feature_id)||!ne(&self.mode)||!ne(&self.scale)||!ne(&self.request_id)||!ne(&self.benchmark_id)||self.boundary!=PRECLINICAL_BOUNDARY||!self.raw_data_local||!self.aggregate_only||self.observation_order.is_empty()||!ord(&self.observation_order)||!ord(&self.passed_order)||!ord(&self.failed_order)||!ord(&self.unknown_order)||!ord(&self.unmeasured_order)||!ord(&self.contradicted_order)||!ord(&self.omitted_order)||!ord(&self.baseline_delta_order)||!ord(&self.uncertainty_order)||!ord(&self.negative_evidence_order)||!ord(&self.site_order)||!ord(&self.metric_order)||!dig(&self.replay_identity)||!dig(&self.evaluation_digest)||self.artifact.content_type!=CONTENT_TYPE||self.artifact.content_hash!=self.evaluation_digest||self.artifact.boundary!=PRECLINICAL_BOUNDARY||!self.effect_receipts.is_empty()&&self.effect_receipts.iter().any(|e|e!="block:unsafe-release"&&!e.starts_with("emit:evaluation-card:")){return Err(EvaluationObservabilityError::Output("evaluation identity, ordering, locality, digest, or effect is invalid".into()))}let ids=BTreeSet::from_iter(self.observation_order.iter().cloned());let parts=self.passed_order.iter().chain(&self.failed_order).chain(&self.unknown_order).chain(&self.unmeasured_order).chain(&self.contradicted_order).chain(&self.omitted_order).cloned().collect::<Vec<_>>();if ids.len()!=self.observation_order.len()||parts.len()!=ids.len()||BTreeSet::from_iter(parts)!=ids{return Err(EvaluationObservabilityError::Output("evaluation states do not partition".into()))}Ok(())}pub fn digest(&self)->Result<ContentHash,EvaluationObservabilityError>{self.validate()?;let value=serde_json::to_value(self).map_err(|e|EvaluationObservabilityError::Output(e.to_string()))?;ContentHash::of_value(&value).map_err(|e|EvaluationObservabilityError::Output(e.to_string()))}}
pub fn evaluate(request:&EvaluationRequest4,id:&str,version:&str,scale:&str,mode:&str)->Result<EvaluationCard8,EvaluationObservabilityError>{if !ne(&request.request_id)||!ne(&request.scope)||!ne(&request.benchmark_id)||request.observations.is_empty()||request.required_metric_order.is_empty()||request.min_pass_fraction_milli>1000||!dig(&request.replay_identity)||!request.raw_data_local||!request.aggregate_only||request.boundary!=PRECLINICAL_BOUNDARY||!ord(&request.required_metric_order)||!ord(&request.adversarial_events){return Err(EvaluationObservabilityError::Invalid("evaluation request identity, metrics, digest, ordering, locality, or boundary is invalid".into()))}let mut rows=request.observations.clone();rows.sort_by(|a,b|a.observation_id.cmp(&b.observation_id));let order=rows.iter().map(|o|o.observation_id.clone()).collect::<Vec<_>>();let mut seen=BTreeSet::new();let mut passed=BTreeSet::new();let mut failed=BTreeSet::new();let mut unknown=BTreeSet::new();let mut unmeasured=BTreeSet::new();let mut contradicted=BTreeSet::new();let mut omitted=BTreeSet::new();let mut baseline=BTreeSet::new();let mut uncertainty=BTreeSet::new();let mut negative=BTreeSet::new();let mut sites=BTreeSet::new();let mut metrics=BTreeSet::new();let mut provenance=BTreeSet::new();for o in &rows{if !seen.insert(o.observation_id.clone())||!ne(&o.observation_id)||!ne(&o.metric)||!ne(&o.independent_site)||!dig(&o.provenance_digest)||!dig(&o.replay_identity){return Err(EvaluationObservabilityError::Invalid("observation identity or digest is invalid".into()))}sites.insert(o.independent_site.clone());metrics.insert(o.metric.clone());provenance.insert(o.provenance_digest.clone());baseline.insert(format!("{}:delta={}",o.observation_id,o.value_milli-o.baseline_milli));if o.uncertainty_milli>0{uncertainty.insert(format!("{}:uncertainty={}",o.observation_id,o.uncertainty_milli));}if o.negative_result{negative.insert(format!("{}:negative-result",o.observation_id));}if o.replay_identity!=request.replay_identity||!o.local||!o.aggregate_only{omitted.insert(o.observation_id.clone());}else{match o.evidence_state.as_str(){"proven"|"supported" if o.value_milli>=o.baseline_milli=>{passed.insert(o.observation_id.clone());},"proven"|"supported"=>{failed.insert(o.observation_id.clone());},"unknown"=>{unknown.insert(o.observation_id.clone());},"unmeasured"=>{unmeasured.insert(o.observation_id.clone());},"contradicted"=>{contradicted.insert(o.observation_id.clone());},_=>{unknown.insert(o.observation_id.clone());}}}}let global=!request.policy_allowed||!request.protected_closure||!request.signed_approval||!request.network_available||!request.raw_data_local||!request.aggregate_only||!request.adversarial_events.is_empty()||mode=="copilot"&&(request.action_budget==0||request.action_count>request.action_budget);if global{omitted.extend(order.iter().cloned());passed.clear();failed.clear();unknown.clear();unmeasured.clear();contradicted.clear();uncertainty.insert("request:global-evaluation-gate-blocked".into());}let p=passed.iter().cloned().collect::<Vec<_>>();let f=failed.iter().cloned().collect::<Vec<_>>();let u=unknown.iter().cloned().collect::<Vec<_>>();let um=unmeasured.iter().cloned().collect::<Vec<_>>();let c=contradicted.iter().cloned().collect::<Vec<_>>();let om=omitted.iter().cloned().collect::<Vec<_>>();let disposition=if global{"blocked"}else if p.is_empty(){"unresolved"}else if (p.len()*1000)/(order.len().max(1))<(request.min_pass_fraction_milli as usize){"unresolved"}else if !f.is_empty()||!u.is_empty()||!um.is_empty()||!c.is_empty()||!om.is_empty(){"unresolved"}else{"qualified"};let stage=request.stage_order.clone();let mut payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":version,"feature_id":id,"mode":mode,"scale":scale,"request_id":request.request_id,"benchmark_id":request.benchmark_id,"disposition":disposition,"observation_order":order,"passed_order":p,"failed_order":f,"unknown_order":u,"unmeasured_order":um,"contradicted_order":c,"omitted_order":om,"baseline_delta_order":baseline.into_iter().collect::<Vec<_>>(),"uncertainty_order":uncertainty.into_iter().collect::<Vec<_>>(),"negative_evidence_order":negative.into_iter().collect::<Vec<_>>(),"site_order":sites.into_iter().collect::<Vec<_>>(),"metric_order":metrics.into_iter().collect::<Vec<_>>(),"stage_order":stage,"completed_stage_order":request.completed_stage_order,"replay_identity":request.replay_identity,"schema_digest":request.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let digest=ContentHash::of_value(&payload).map_err(|e|EvaluationObservabilityError::Output(e.to_string()))?;payload["evaluation_digest"]=json!(digest);payload["artifact"]=json!({"artifact_id":format!("worldgen-evaluation-card:{}",request.request_id),"content_type":CONTENT_TYPE,"content_hash":digest,"semantic_loss":payload["omitted_order"],"provenance_digests":provenance.into_iter().collect::<Vec<_>>(),"boundary":PRECLINICAL_BOUNDARY});payload["effect_receipts"]=json!(if disposition=="qualified"{vec![format!("emit:evaluation-card:{}",request.request_id)]}else{vec!["block:unsafe-release".to_string()]});let out:EvaluationCard8=serde_json::from_value(payload).map_err(|e|EvaluationObservabilityError::Output(e.to_string()))?;out.validate()?;Ok(out)}
#[cfg(test)]mod tests{use super::*;fn h(v:&str)->ContentHash{ContentHash::of_bytes(v.as_bytes())}fn q()->EvaluationRequest4{EvaluationRequest4{request_id:"eval:req".into(),scope:"study:local".into(),benchmark_id:"bench:1".into(),observations:vec![EvaluationObservation4{observation_id:"obs:a".into(),metric:"rate".into(),value_milli:900,baseline_milli:800,uncertainty_milli:5,evidence_state:"proven".into(),provenance_digest:h("p"),replay_identity:h("r"),independent_site:"site:a".into(),negative_result:false,local:true,aggregate_only:true}],required_metric_order:vec!["rate".into()],min_pass_fraction_milli:800,policy_allowed:true,protected_closure:true,signed_approval:true,network_available:true,raw_data_local:true,aggregate_only:true,replay_identity:h("r"),adversarial_events:vec![],action_budget:2,action_count:1,stage_order:vec![],completed_stage_order:vec![],boundary:PRECLINICAL_BOUNDARY.into()}}#[test]fn qualified(){assert_eq!(evaluate(&q(),FEATURE_ID,CONTRACT_VERSION,"local single-study","inference").unwrap().disposition,"qualified")}#[test]fn unknown_is_unresolved(){let mut x=q();x.observations[0].evidence_state="unknown".into();assert_eq!(evaluate(&x,FEATURE_ID,CONTRACT_VERSION,"local single-study","inference").unwrap().disposition,"unresolved")}#[test]fn policy_blocks(){let mut x=q();x.policy_allowed=false;assert_eq!(evaluate(&x,FEATURE_ID,CONTRACT_VERSION,"local single-study","inference").unwrap().disposition,"blocked")}}


